const crypto = require('crypto');
const h = $json.headers, raw = $json.rawBody ? $json.rawBody.toString() : JSON.stringify($json.body);
const ts = h['x-timestamp'], sig = h['x-signature'], id = h['x-event-id'];
if (!ts || Math.abs(Date.now()/1000 - Number(ts)) > 300) throw new Error('stale or missing timestamp');
const exp = crypto.createHmac('sha256', $env.GROWTH_HMAC_SECRET).update(ts + '.' + raw).digest('hex');
if (!sig || sig.length !== exp.length || !crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(exp))) throw new Error('bad signature');
const seen = $getWorkflowStaticData('global'); seen.ids = seen.ids || {};
const now = Date.now(); for (const k of Object.keys(seen.ids)) if (now - seen.ids[k] > 86400000) delete seen.ids[k];
if (seen.ids[id]) return []; // duplicate delivery: Laravel retries until 2xx
seen.ids[id] = now;
return [{ json: { event_id: id, type: h['x-event-type'], event: $json.body } }];

// HMAC-SHA256(secret, "{timestamp}.{raw body}") -> X-Signature. Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto. Secret comes from env, never from this file.
const crypto = require('crypto');
const base = $env.GROWTH_API_BASE.replace(/\/$/, '');
const secret = $env.GROWTH_HMAC_SECRET;
const T = $('Webhook').first().json; // trigger payload
const req = {method:"GET",path:"/features"};
const body = req.body ? JSON.stringify(req.body) : '';
const ts = String(Math.floor(Date.now() / 1000));
const sig = crypto.createHmac('sha256', secret).update(ts + '.' + body).digest('hex');
const headers = { 'X-Timestamp': ts, 'X-Signature': sig, 'Accept': 'application/json' };
if (body) { headers['Content-Type'] = 'application/json'; headers['Idempotency-Key'] = req.idem || crypto.createHash('sha256').update(req.path + body).digest('hex'); }
return [{ json: { url: base + req.path, method: req.method, body, headers, ctx: $json } }];

