// Builds a short, customer-data-free summary of this run's API responses and passes it to "99 Notify owner". Edit freely.
const CALLS = ["Call health"];
const short = (v) => { const s = typeof v === 'string' ? v : JSON.stringify(v); return s.length > 160 ? s.slice(0, 157) + '...' : s; };
const describe = (d) => {
  if (Array.isArray(d)) return d.length + ' item(s)' + (d.length ? ': ' + d.slice(0, 3).map(short).join(' | ') : '');
  if (d && typeof d === 'object') return Object.entries(d).slice(0, 10).map(([k, v]) => k + ': ' + (Array.isArray(v) ? v.length + ' item(s)' : short(v))).join('\n   ');
  return short(d);
};
const lines = [];
for (const n of CALLS) {
  try {
    const r = $(n).first().json;
    lines.push('• ' + n.replace(/^Call /, '') + (r && r.success === false ? ' (FAILED)' : '') + '\n   ' + describe(r && r.data !== undefined ? r.data : r));
  } catch (e) { /* that node did not run in this execution */ }
}
const text = lines.join('\n\n').slice(0, 3500) || 'No data returned.';
return [{ json: { title: $workflow.name, text } }];
